    closeApp() {
      this.$ui.closeApp(this.app)
    },
    toggleFullscreen() {
      const panelId = this.app?.tabId
      if (!panelId) return

      // Toggle fullscreen state in store and dockview
      if (this.isFullscreen) {
        this.$storex.ui.clearFullscreenPanel()
      } else {
        this.$storex.ui.setFullscreenPanel(panelId)
      }

      // Call dockview API to actually maximize/restore the panel
      this.$storex.ui.togglePanelFullscreen(panelId)
    }
  }
}
