## Key Changes

| Change | Details |
|--------|---------|
| **Added `fullscreenPanelId` computed** | Watches store fullscreen state |
| **Added `isApplyingFullscreen` flag** | Prevents infinite loops between store and API |
| **Added watcher for `fullscreenPanelId`** | Calls `applyFullscreenState()` when store changes |
| **New `applyFullscreenState()` method** | Calls `maximizePanel()` or `restorePanel()` on dockview API |
| **Updated `setupPanelEventHandlers()`** | Renamed from before, syncs dockview events to store (bidirectional) |
| **Bidirectional sync** | Store → API and API → Store without infinite loops |

**How it works:**
1. User clicks fullscreen icon → `AppIcon.vue` calls `$storex.ui.setFullscreenPanel(panelId)`
2. Desktop watcher detects change → calls `dockviewApi.maximizePanel(panel)`
3. Dockview API triggers `onDidMaximizePanel` → updates store (with flag to prevent loop)
4. User presses ESC in dockview → triggers `onDidRestorePanel` → clears store state
5. AppIcon icon automatically updates based on `isFullscreen` computed property

In the react example below, they show an icon on the right of the group tabs header to toggle the full screen. Full screen is for the whole group and not only for a tab, so it makes sense to remove the icon from the AppIcon and place on the header instead.

Analuyze this react exampla and apply to our vue components to toggle full screen from a group menu

```tsx
import 'dockview-vue/dist/styles/dockview.css';
import { PropType, createApp, defineComponent } from 'vue';

import {
    DockviewVue,
    DockviewReadyEvent,
    IDockviewHeaderActionsProps,
    IDockviewPanelProps,
} from 'dockview-vue';

let panelCount = 0;

const MaterialIcon = defineComponent({
    name: 'MaterialIcon',
    props: {
        icon: {
            type: String,
            required: true,
        },
        title: {
            type: String,
            required: false,
        },
    },
    emits: ['click'],
    data() {
        return {
            title: this.title,
            icon: this.icon,
        };
    },
    methods: {
        onClick() {
            this.$emit('click');
        },
    },
    template: `
      <div
        @click="onClick"
        title="title"
        style="display:flex;justify-content:center;align-items:center;width:30px;height:100%;font-size:18px;">
          <span class="material-symbols-outlined" style="font-size:inherit;cursor:pointer;">
            {{icon}}
          </span>
      </div>`,
});

const LeftAction = defineComponent({
    name: 'LeftAction',
    props: {
        params: {
            type: Object as PropType<IDockviewHeaderActionsProps>,
            required: true,
        },
    },
    components: {
        'material-icon': MaterialIcon,
    },
    methods: {
        onClick() {
            this.parmas.containerApi.addPanel({
                id: (++panelCount).toString(),
                title: `Tab ${panelCount}`,
                component: 'default',
                position: { referenceGroup: this.params.group },
            });
        },
    },
    template: `
      <div style="height:100%;padding:0px 4px;">
        <material-icon @click="onClick" icon="add"></material-icon>
      </div>`,
});

const RightAction = defineComponent({
    name: 'RightAction',
    props: {
        params: {
            type: Object as PropType<IDockviewHeaderActionsProps>,
            required: true,
        },
    },
    data() {
        return {
            maximized: false,
        };
    },
    mounted() {
        const disposable = this.params.containerApi.onDidMaximizedGroupChange(
            () => {
                this.maximized = this.api.isMaximized();
            }
        );

        this.maximized = this.api.isMaximized();

        return () => {
            disposable.dispose();
        };
    },
    components: {
        'material-icon': MaterialIcon,
    },
    methods: {
        onClick() {
            if (this.maximized) {
                this.api.exitMaximized();
            } else {
                this.api.maximize();
            }
        },
    },
    template: `
      <div style="height:100%;padding:0px 4px;">
        <material-icon v-if="maximized" @click="onClick" icon="jump_to_element" ></material-icon>
        <material-icon v-if="!maximized" @click="onClick" icon="back_to_tab"></material-icon>
      </div>`,
});

const Panel = defineComponent({
    name: 'Panel',
    props: {
        params: {
            type: Object as PropType<IDockviewPanelProps>,
            required: true,
        },
    },
    data() {
        return {
            title: '',
        };
    },

    mounted() {
        const disposable = this.params.api.onDidTitleChange(() => {
            this.title = this.api.title;
        });
        this.title = this.api.title;

        return () => {
            disposable.dispose();
        };
    },
    template: `<div class="example-panel">{{ title }}</div>`,
});

const App = defineComponent({
    name: 'App',
    components: {
        'dockview-vue': DockviewVue,
        default: Panel,
        leftAction: LeftAction,
        rightAction: RightAction,
    },
    methods: {
        onReady(event: DockviewReadyEvent) {
            event.api.addPanel({
                id: 'panel_1',
                component: 'default',
                title: 'Panel 1',
            });
            event.api.addPanel({
                id: 'panel_2',
                component: 'default',
                title: 'Panel 2',
                position: {
                    direction: 'right',
                    referencePanel: 'panel_1',
                },
            });
            event.api.addPanel({
                id: 'panel_3',
                component: 'default',
                title: 'Panel 3',
                position: {
                    direction: 'below',
                    referencePanel: 'panel_1',
                },
            });
            event.api.addPanel({
                id: 'panel_4',
                component: 'default',
                title: 'Panel 4',
            });
            event.api.addPanel({
                id: 'panel_5',
                component: 'default',
                title: 'Panel 5',
            });
        },
    },
    computed: {
        styleObject() {
            return {
                height: `${this.value}%`,
                width: `${this.value}%`,
            };
        },
    },
    template: `
      <dockview-vue
        style="width:100%;height:100%"
        className="${(window as any).__dockviewThemeClass ?? 'dockview-theme-abyss'}"
        @ready="onReady"
        leftHeaderActionsComponent="leftAction"
        rightHeaderActionsComponent="rightAction"
      ></dockview-vue>`,
});

const app = createApp(App);
app.config.errorHandler = (err) => {
    console.log(err);
};
app.mount(document.getElementById('app')!);
