<script setup>
import { computed, onMounted, ref } from 'vue'
</script>

<template>
  <div class="h-full px-1 flex items-center gap-1">
    <!-- Fullscreen toggle button -->
    <button
      @click="toggleFullscreen"
      class="btn btn-ghost btn-xs gap-1 text-base-content hover:bg-base-300"
      :title="isMaximized ? 'Exit fullscreen' : 'Enter fullscreen'"
    >
      <i v-if="isMaximized" class="fa-solid fa-compress text-sm"></i>
      <i v-else class="fa-solid fa-expand text-sm"></i>
    </button>
  </div>
</template>

<script>
export default {
  props: {
    params: {
      type: Object,
      required: true
    }
  },
  data() {
    return {
      isMaximized: false
    }
  },
  computed: {
    groupApi() {
      return this.params.group
    },
    containerApi() {
      return this.params.containerApi
    }
  },
  methods: {
    toggleFullscreen() {
      if (this.isMaximized) {
        this.groupApi.exitMaximized()
      } else {
        this.groupApi.maximize()
      }
    },
    setupMaximizedListener() {
      if (!this.containerApi) return

      const disposable = this.containerApi.onDidMaximizedGroupChange(() => {
        this.updateMaximizedState()
      })

      this.updateMaximizedState()

      return () => {
        disposable.dispose()
      }
    },
    updateMaximizedState() {
      this.isMaximized = this.groupApi.isMaximized()
    }
  },
  mounted() {
    const cleanup = this.setupMaximizedListener()
    this.$once('hook:beforeDestroy', () => {
      if (cleanup) cleanup()
    })
  }
}
</script>

